class ChunkedUploader{constructor(file,options={}){this.file=file;this.chunkSize=options.chunkSize||2*1024*1024;this.uploadUrl=options.uploadUrl||"/upload/chunk";this.onProgress=options.onProgress||(()=>{});this.onSuccess=options.onSuccess||(()=>{});this.onError=options.onError||(()=>{});this.totalChunks=Math.ceil(this.file.size/this.chunkSize);this.currentChunk=0;this.uploadId=Date.now().toString(36)+Math.random().toString(36).substr(2);this.isPaused=false}start(){this.uploadNextChunk()}uploadNextChunk(){if(this.currentChunk>=this.totalChunks||this.isPaused){return}const start=this.currentChunk*this.chunkSize;const end=Math.min(start+this.chunkSize,this.file.size);const chunk=this.file.slice(start,end);const formData=new FormData;formData.append("file_data",chunk);formData.append("file_name",this.file.name);formData.append("chunk_index",this.currentChunk);formData.append("total_chunks",this.totalChunks);formData.append("upload_id",this.uploadId);const xhr=new XMLHttpRequest;xhr.open("POST",this.uploadUrl,true);if(window.CSRF_TOKEN){xhr.setRequestHeader("X-CSRF-TOKEN",window.CSRF_TOKEN)}xhr.onload=()=>{if(xhr.status===200){try{const response=JSON.parse(xhr.responseText);if(response.status==="success"){this.currentChunk++;this.onProgress(100);this.onSuccess(response.file_path)}else if(response.status==="progress"||response.status==="chunk_uploaded"){this.currentChunk++;const percent=Math.round(this.currentChunk/this.totalChunks*100);this.onProgress(percent);this.uploadNextChunk()}else{this.onError("Server Error: "+(response.message||"Unknown"))}}catch(e){this.onError("Invalid JSON response")}}else{this.onError("Upload failed with status "+xhr.status)}};xhr.onerror=()=>{this.onError("Network Error")};xhr.send(formData)}}window.initChunkedUploader=function(fileInputId,progressBarId,hiddenInputId,uploadButtonId){const fileInput=document.getElementById(fileInputId);const progressBar=document.getElementById(progressBarId);const hiddenInput=document.getElementById(hiddenInputId);const uploadButton=document.getElementById(uploadButtonId);if(!fileInput)return;fileInput.addEventListener("change",()=>{const file=fileInput.files[0];if(!file)return;progressBar.style.width="0%";progressBar.innerText="0%";progressBar.parentElement.classList.remove("hidden");if(uploadButton)uploadButton.disabled=true;const uploader=new ChunkedUploader(file,{onProgress:percent=>{progressBar.style.width=percent+"%";progressBar.innerText=percent+"%"},onSuccess:url=>{hiddenInput.value=url;progressBar.classList.add("bg-green-600");progressBar.innerText="Upload Complete";if(uploadButton)uploadButton.disabled=false;console.log("File available at:",url)},onError:err=>{progressBar.classList.add("bg-red-600");progressBar.innerText="Error";console.error(err);alert("Upload Failed: "+err);if(uploadButton)uploadButton.disabled=false}});uploader.start()})};